1	<html>
2	    <head>
3	        <title>2D Fluid Simulation</title>
4	        <style>
5	            * {padding: 0; margin: 0;}
6	            canvas { display: block; margin: 20px auto;}
7	            body {background: #242321;}
8	        </style>
9	    </head>
10	
11	    <body>
12	        <canvas id="canvas" width="1280px" height="720px" style="border: solid 1px black"></canvas>
13	        <script src="Playground.js"></script>
14	        <script src="Simulation.js"></script>
15	        <script src="Vector2.js"></script>
16	        <script src="DrawUtils.js"></script>
17	        <script src="Particle.js"></script>
18	        <script src="FluidHashGrid.js"></script>
19	        <script src="ParticleEmitter.js"></script>
20	        <script src="Spring.js"></script>
21	        <script src="shapes/Shape.js"></script>
22	        <script src="shapes/Polygon.js"></script>
23	        <script src="shapes/Circle.js"></script>
24	
25	        <script>
26	            var canvas = document.getElementById("canvas");
27	            var ctx = canvas.getContext("2d");
28	
29	            // --- metaball fluid rendering pipeline ---
30	            // offscreen canvas: particles drawn as soft white blobs
31	            var particleCanvas = document.createElement("canvas");
32	            particleCanvas.width = canvas.width;
33	            particleCanvas.height = canvas.height;
34	            var particleCtx = particleCanvas.getContext("2d");
35	
36	            // offscreen canvas: final thresholded + tinted fluid surface
37	            var fluidCanvas = document.createElement("canvas");
38	            fluidCanvas.width = canvas.width;
39	            fluidCanvas.height = canvas.height;
40	            var fluidCtx = fluidCanvas.getContext("2d");
41	
42	            // pre-rendered soft white sprite (drawn once, reused per particle)
43	            var FLUID_RADIUS = 13;
44	            var spriteSize = 64;
45	            var fluidSprite = document.createElement("canvas");
46	            fluidSprite.width = spriteSize;
47	            fluidSprite.height = spriteSize;
48	            (function buildSprite(){
49	                let sctx = fluidSprite.getContext("2d");
50	                let g = sctx.createRadialGradient(spriteSize/2, spriteSize/2, 0, spriteSize/2, spriteSize/2, spriteSize/2);
51	                g.addColorStop(0.0, "rgba(255,255,255,1)");
52	                g.addColorStop(0.4, "rgba(255,255,255,0.85)");
53	                g.addColorStop(1.0, "rgba(255,255,255,0)");
54	                sctx.fillStyle = g;
55	                sctx.fillRect(0,0,spriteSize,spriteSize);
56	            })();
57	            window.fluidSprite = fluidSprite;
58	            window.FLUID_RADIUS = FLUID_RADIUS;
59	
60	            // metaball tuning
61	            var FLUID_BLUR = 10;       // px, controls how far blobs bleed together
62	            var FLUID_CONTRAST = 18;   // threshold sharpness; higher = crisper surface
63	
64	            let lastTime = performance.now();
65	            let currentTime = 0;
66	            let deltaTime = 0;
67	
68	            let playground = new Playground();
69	
70	            mainLoop();
71	
72	            function updatePlayground(dt){
73	                playground.update(dt);
74	
75	                // 1. background
76	                ctx.fillStyle = "#242321";
77	                ctx.fillRect(0,0, canvas.width, canvas.height);
78	
79	                // 2. draw particles as soft white blobs onto offscreen canvas
80	                particleCtx.clearRect(0,0, particleCanvas.width, particleCanvas.height);
81	                playground.drawFluid(particleCtx);
82	
83	                // 3. metaball pass: blur neighbours together, contrast threshold
84	                //    creates crisp alpha mask, then tint it blue with a depth gradient
85	                fluidCtx.clearRect(0,0, fluidCanvas.width, fluidCanvas.height);
86	                fluidCtx.save();
87	                fluidCtx.filter = "blur(" + FLUID_BLUR + "px) contrast(" + FLUID_CONTRAST + ")";
88	                fluidCtx.drawImage(particleCanvas, 0, 0);
89	                fluidCtx.filter = "none";
90	                fluidCtx.globalCompositeOperation = "source-in";
91	                let depthGrad = fluidCtx.createLinearGradient(0, 0, 0, fluidCanvas.height);
92	                depthGrad.addColorStop(0, "#5fc7ff");
93	                depthGrad.addColorStop(1, "#0a5a9e");
94	                fluidCtx.fillStyle = depthGrad;
95	                fluidCtx.fillRect(0, 0, fluidCanvas.width, fluidCanvas.height);
96	                fluidCtx.restore();
97	
98	                // 4. composite the fluid surface onto the main canvas
99	                ctx.drawImage(fluidCanvas, 0, 0);
100	
101	                // 5. draw obstacles & emitters crisply on top
102	                playground.draw();
103	            }
104	
105	            function mainLoop(){
106	                window.requestAnimationFrame(mainLoop);
107	
108	                currentTime = performance.now();
109	                deltaTime = (currentTime - lastTime) / 1000;
110	
111	                updatePlayground(deltaTime);
112	                lastTime = currentTime;
113	            }
114	
115	            function getMousePos(canvas, evt){
116	                var rect = canvas.getBoundingClientRect();
117	                return {
118	                    x: evt.clientX - rect.left,
119	                    y: evt.clientY - rect.top
120	                };
121	            }
122	
123	            canvas.addEventListener('mousemove', function(evt){
124	                let mouse = getMousePos(canvas,evt);
125	                playground.onMouseMove(new Vector2(mouse.x,mouse.y));
126	            }, false)
127	
128	            canvas.addEventListener('mousedown', function(evt){
129	                playground.onMouseDown(evt.button);
130	            }, false)
131	
132	            canvas.addEventListener('mouseup', function(evt){
133	                playground.onMouseUp(evt.button);
134	            }, false)
135	
136	
137	
138	
139	        </script>
140	
141	
142	    </body>
143	
