1	class Simulation{
2	    constructor(){
3	        this.particles = [];
4	        this.particleEmitters = [];
5	        this.shapes = [];
6	        this.springs = new Map();
7	
8	
9	        this.AMOUNT_PARTICLES = 2000;
10	        this.VELOCITY_DAMPING = 0.99;
11	        this.GRAVITY = new Vector2(0,1);
12	        this.REST_DENSITY = 10;
13	        this.K_NEAR = 3;
14	        this.K = 0.5;
15	        this.INTERACTION_RADIUS = 25;
16	
17	        // viscouse parameters
18	        this.SIGMA = 0;
19	        this.BETA = 0;
20	
21	        // plasticity parameters
22	        this.GAMMA = 0.1;
23	        this.PLASTICITY = 0.9;
24	        this.SPRING_STIFFNESS = 1;
25	
26	
27	        this.fluidHashGrid = new FluidHashGrid(this.INTERACTION_RADIUS);
28	        //this.instantiateParticles();
29	        this.fluidHashGrid.initialize(this.particles);
30	
31	
32	        this.emitter = this.createParticleEmitter(
33	            new Vector2(canvas.width / 2 + 400, 400), // position
34	            new Vector2(-1,-1), // direction
35	            20, // size
36	            0.5,  // spawn interval
37	            10, // amount
38	            20  // speed
39	        );
40	
41	        let circle = new Circle(new Vector2(500,700), 100, "orange");
42	        let polygon = new Polygon([
43	            new Vector2(700,450), 
44	            new Vector2(900,450),
45	            new Vector2(900,550),
46	            new Vector2(700,550)],"orange");
47	
48	        this.shapes.push(circle);
49	        this.shapes.push(polygon);
50	
51	    }
52	
53	    createParticleEmitter(position, direction, size, spawnInterval, amount, velocity){
54	        let emitter = new ParticleEmitter(position, direction, size, spawnInterval, amount, velocity);
55	        this.particleEmitters.push(emitter);
56	        return emitter;
57	    }
58	
59	    getShapeAt(pos){
60	        for(let i=0; i< this.shapes.length; i++){
61	            if(this.shapes[i].isPointInside(pos)){
62	                return this.shapes[i];
63	            }
64	        }
65	        return null;
66	    }
67	
68	    instantiateParticles(){
69	        let offsetBetweenParticles = 10;
70	        let offsetAllParticles = new Vector2(750, 100);
71	
72	        let xParticles = Math.sqrt(this.AMOUNT_PARTICLES);
73	        let yParticles = xParticles;
74	
75	
76	        for(let x=0; x< xParticles; x++){
77	            for(let y=0; y< yParticles; y++){
78	                let position = new Vector2(
79	                    x*offsetBetweenParticles + offsetAllParticles.x,
80	                    y*offsetBetweenParticles + offsetAllParticles.y);
81	
82	                let particle = new Particle(position);
83	                //particle.velocity = Scale(new Vector2(-0.5 + Math.random(),-0.5 + Math.random()), 200);
84	
85	
86	                this.particles.push(particle);
87	            }
88	        }
89	    }
90	
91	    neighbourSearch(){
92	        this.fluidHashGrid.clearGrid();
93	        this.fluidHashGrid.mapParticleToCell();
94	    }
95	
96	    update(dt){
97	        this.neighbourSearch();
98	
99	        this.emitter.spawn(dt, this.particles);
100	        if(this.rotate){
101	            this.emitter.rotate(0.01);
102	        }
103	
104	        this.applyGravity(dt);
105	
106	        //this.viscosity(dt);
107	
108	        this.predictPositions(dt);
109	
110	        //this.adjustSprings(dt);
111	        //this.springDisplacement(dt);
112	
113	        this.doubleDensityRelaxation(dt);
114	
115	        this.handleOneWayCoupling();
116	        this.worldBoundary();
117	
118	        this.computeNextVelocity(dt);
119	    }
120	
121	    handleOneWayCoupling(){
122	        for(let i=0; i< this.particles.length; i++){
123	            let particle = this.particles[i];
124	            for(let j=0; j<this.shapes.length;j++){
125	                let dir = this.shapes[j].getDirectionOut(particle.position);
126	                if(dir != null){
127	                    particle.position = Add(particle.position, dir);
128	                }
129	            }
130	        }
131	    }
132	
133	    adjustSprings(dt){
134	        for(let i=0; i< this.particles.length; i++){
135	            let neighbours = this.fluidHashGrid.getNeighbourOfParticleIdx(i);
136	            let particleA = this.particles[i];
137	
138	            for(let j = 0; j < neighbours.length;j++){
139					let particleB = this.particles[neighbours[j]];
140					if(particleA == particleB) continue;
141	
142	                let springId = i + neighbours[j] * this.particles.length;
143	
144	                if(this.springs.has(springId)){
145	                    continue;
146	                }
147	
148	                let rij = Sub(particleB.position,particleA.position); 
149	                let q = rij.Length() / this.INTERACTION_RADIUS;
150	
151	                if(q < 1){
152	                    let newSpring = new Spring(i, neighbours[j], this.INTERACTION_RADIUS);
153	                    this.springs.set(springId, newSpring);
154	                }
155	            }
156	        }
157	
158	
159	        for(let [key, spring] of this.springs){
160	            let pi = this.particles[spring.particleAIdx];
161	            let pj = this.particles[spring.particleBIdx];
162	
163	            let rij = Sub(pi.position, pj.position).Length();
164	            let Lij = spring.length;
165	            let d = this.GAMMA * Lij;
166	
167	            if(rij > Lij + d){
168	                spring.length += dt * this.PLASTICITY * (rij - Lij - d); // stretching
169	
170	            }else if(rij < Lij - d){ 
171	                spring.length -= dt * this.PLASTICITY * (Lij - d - rij); // compression
172	            }
173	
174	            if(spring.length > this.INTERACTION_RADIUS){
175	                this.springs.delete(key);
176	            }
177	        }
178	    }
179	
180	    springDisplacement(dt){
181	        let dtSquared = dt * dt;
182	
183	        for(let [key, spring] of this.springs){
184	            let pi = this.particles[spring.particleAIdx];
185	            let pj = this.particles[spring.particleBIdx];
186	
187	            let rij = Sub(pi.position, pj.position);
188	            let distance = rij.Length();
189	
190	            if(distance < 0.0001){
191	                continue;
192	            }
193	
194	            rij.Normalize();
195	            let displacementTerm = dtSquared * this.SPRING_STIFFNESS * 
196	                (1 - spring.length / this.INTERACTION_RADIUS) * (spring.length - distance);
197	
198	            rij = Scale(rij, displacementTerm * 0.5);
199	
200	            pi.position = Add(pi.position, rij);
201	            pj.position = Sub(pj.position, rij);
202	        }
203	    }
204	
205	    viscosity(dt){
206	        for(let i=0; i< this.particles.length; i++){
207				let neighbours = this.fluidHashGrid.getNeighbourOfParticleIdx(i);
208				let particleA = this.particles[i];
209	
210	            for(let j = 0; j < neighbours.length;j++){
211					let particleB = this.particles[neighbours[j]];
212					if(particleA == particleB) continue;
213	
214	                let rij = Sub(particleB.position,particleA.position);
215	                let velocityA = particleA.velocity;
216	                let velocityB = particleB.velocity;
217	                let q = rij.Length() / this.INTERACTION_RADIUS;
218	                
219	                if(q < 1){
220	
221	                    rij.Normalize();
222	                    let u = Sub(velocityA, velocityB).Dot(rij);
223	
224	                    if(u > 0){
225	                        let ITerm = dt * (1-q) * (this.SIGMA * u + this.BETA * u * u);
226	                        let I = Scale(rij, ITerm);
227	
228	                        particleA.velocity = Sub(particleA.velocity, Scale(I, 0.5));
229	                        particleB.velocity = Add(particleB.velocity, Scale(I, 0.5));
230	                    }
231	                }
232	            }
233	        }
234	    }
235	
236	    doubleDensityRelaxation(dt){
237	        for(let i=0; i< this.particles.length; i++){
238				let density = 0;
239				let densityNear = 0;
240				let neighbours = this.fluidHashGrid.getNeighbourOfParticleIdx(i);
241				let particleA = this.particles[i];
242	
243				for(let j = 0; j < neighbours.length;j++){
244					let particleB = this.particles[neighbours[j]];
245					if(particleA == particleB) continue;
246					
247					
248					let rij = Sub(particleB.position,particleA.position);
249					let q = rij.Length() / this.INTERACTION_RADIUS;
250					
251					if(q < 1){
252						let oneMinusQ = (1-q);
253						density += oneMinusQ*oneMinusQ;
254						densityNear += oneMinusQ*oneMinusQ*oneMinusQ;					
255					}
256				}
257	
258	            let pressure = this.K * (density - this.REST_DENSITY);
259	            let pressureNear = this.K_NEAR * densityNear;
260	            let particleADisplacement = Vector2.Zero();
261	
262	            
263	            for(let j=0; j< neighbours.length; j++){
264	                let particleB = this.particles[neighbours[j]];
265	                if(particleA == particleB){
266	                    continue;
267	                }
268	
269	                let rij = Sub(particleB.position, particleA.position);
270	                let q = rij.Length() / this.INTERACTION_RADIUS;
271	
272	                if(q < 1.0){
273	                    rij.Normalize();
274	                    let displacementTerm = Math.pow(dt, 2) * 
275	                        (pressure * (1-q) + pressureNear * Math.pow(1-q, 2));
276	                    let D = Scale(rij, displacementTerm);
277	
278	                    particleB.position = Add(particleB.position, Scale(D,0.5));
279	                    particleADisplacement = Sub(particleADisplacement, Scale(D,0.5));
280	                }
281	            }
282	            particleA.position = Add(particleA.position, particleADisplacement);
283	        }
284	    }
285	
286	    applyGravity(dt){
287	        for(let i=0; i< this.particles.length; i++){
288	            this.particles[i].velocity = Add(this.particles[i].velocity, Scale(this.GRAVITY, dt));
289	        }
290	    }
291	
292	    predictPositions(dt){
293	        for(let i=0; i< this.particles.length; i++){
294	            this.particles[i].prevPosition = this.particles[i].position.Cpy();
295	            let positionDelta = Scale(this.particles[i].velocity, dt * this.VELOCITY_DAMPING);
296	            this.particles[i].position = Add(this.particles[i].position, positionDelta);
297	        }
298	    }
299	
300	    computeNextVelocity(dt){
301	        for(let i=0; i< this.particles.length; i++){
302	            let velocity = Scale(Sub(this.particles[i].position, this.particles[i].prevPosition), 1.0 / dt);
303	            this.particles[i].velocity = velocity;
304	        }
305	    }
306	
307	    worldBoundary(){
308	        for(let i=0; i< this.particles.length; i++){
309	            let pos = this.particles[i].position;
310	
311	            if(pos.x < 0){
312	                this.particles[i].position.x = 0;
313	                this.particles[i].prevPosition.x = 0;
314	            }
315	            if(pos.y < 0){
316	                this.particles[i].position.y = 0;
317	                this.particles[i].prevPosition.y = 0;
318	            }
319	            if(pos.x > canvas.width){
320	                this.particles[i].position.x = canvas.width-1;
321	                this.particles[i].prevPosition.x = canvas.width-1;
322	            }
323	            if(pos.y > canvas.height){
324	                this.particles[i].position.y = canvas.height-1;
325	                this.particles[i].prevPosition.y = canvas.height-1;
326	            }
327	        }
328	    }
329	
330	
331	    drawFluid(targetCtx){
332	        let r = window.FLUID_RADIUS;
333	        let d = r * 2;
334	        let sprite = window.fluidSprite;
335	        for(let i=0; i < this.particles.length; i++){
336	            let p = this.particles[i];
337	            targetCtx.drawImage(sprite, p.position.x - r, p.position.y - r, d, d);
338	        }
339	    }
340	
341	    draw(){
342	        for(let i=0; i< this.shapes.length; i++){
343	            this.shapes[i].draw();
344	        }
345	
346	        for(let i=0; i < this.particleEmitters.length; i++){
347	            this.particleEmitters[i].draw();
348	        }
349	    }
350	}

