// --- metaball fluid rendering pipeline ---
// helper: create an offscreen canvas matched to the main one
function makeLayer(){
    let c = document.createElement("canvas");
    c.width = canvas.width;
    c.height = canvas.height;
    return c;
}

// offscreen canvas: particles drawn as soft white blobs (the density field)
var particleCanvas = makeLayer();
var particleCtx = particleCanvas.getContext("2d");

// offscreen masks derived from the field at different thresholds
var surfCanvas = makeLayer();   // full fluid surface (outer threshold)
var surfCtx = surfCanvas.getContext("2d");
var coreCanvas = makeLayer();   // eroded interior (inner threshold)
var coreCtx = coreCanvas.getContext("2d");
var layerCanvas = makeLayer();  // scratch canvas for tinting each layer
var layerCtx = layerCanvas.getContext("2d");

// pre-rendered soft white sprite (drawn once, reused per particle)
var FLUID_RADIUS = 14;
var spriteSize = 64;
var fluidSprite = document.createElement("canvas");
fluidSprite.width = spriteSize;
fluidSprite.height = spriteSize;
(function buildSprite(){
    let sctx = fluidSprite.getContext("2d");
    let g = sctx.createRadialGradient(spriteSize/2, spriteSize/2, 0, spriteSize/2, spriteSize/2, spriteSize/2);
    g.addColorStop(0.0, "rgba(255,255,255,1)");
    g.addColorStop(0.45, "rgba(255,255,255,0.9)");
    g.addColorStop(1.0, "rgba(255,255,255,0)");
    sctx.fillStyle = g;
    sctx.fillRect(0,0,spriteSize,spriteSize);
})();
window.fluidSprite = fluidSprite;
window.FLUID_RADIUS = FLUID_RADIUS;

// metaball tuning
var FLUID_BLUR = 9;          // px, controls how far blobs bleed together
var FLUID_CONTRAST = 16;     // threshold sharpness; higher = crisper surface
var CORE_BRIGHTNESS = 0.7;   // <1 erodes the field -> smaller interior mask

// fill the given mask canvas with a paint, keeping only the mask's shape.
// paint is either a CSS color string or a function(ctx)->gradient.
function paintMask(maskCanvas, paint, blurPx){
    layerCtx.setTransform(1,0,0,1,0,0);
    layerCtx.globalCompositeOperation = "source-over";
    layerCtx.clearRect(0,0,layerCanvas.width,layerCanvas.height);
    layerCtx.filter = blurPx ? ("blur(" + blurPx + "px)") : "none";
    layerCtx.drawImage(maskCanvas, 0, 0);
    layerCtx.filter = "none";
    layerCtx.globalCompositeOperation = "source-in";
    layerCtx.fillStyle = (typeof paint === "function") ? paint(layerCtx) : paint;
    layerCtx.fillRect(0,0,layerCanvas.width,layerCanvas.height);
    layerCtx.globalCompositeOperation = "source-over";
    return layerCanvas;
}

let lastTime = performance.now();

