const { chromium } = require('playwright');

(async () => {
  const lesson = process.argv[2] || '12. Particle Collisions';
  const out = process.argv[3] || 'shot.png';
  const waitMs = parseInt(process.argv[4] || '6000', 10);
  const url = 'file://' + require('path').resolve(lesson, 'Main.html');

  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1320, height: 760 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push(e.message));
  await page.goto(url);
  await page.waitForTimeout(waitMs);
  const canvas = await page.$('#canvas');
  await canvas.screenshot({ path: out });
  await browser.close();
  if (errors.length) { console.log('PAGE ERRORS:\n' + errors.join('\n')); }
  console.log('saved ' + out);
})();

