function updatePlayground(dt){
    playground.update(dt);

    // 1. background
    ctx.fillStyle = "#242321";
    ctx.fillRect(0,0, canvas.width, canvas.height);

    // 2. draw particles as soft white blobs onto the density-field canvas
    particleCtx.clearRect(0,0, particleCanvas.width, particleCanvas.height);
    playground.drawFluid(particleCtx);

    // 3. threshold the field into two alpha masks at different levels.
    //    surfCanvas = the full fluid surface; coreCanvas = an eroded
    //    interior. The shell between them is the surface/rim of the water.
    surfCtx.setTransform(1,0,0,1,0,0);
    surfCtx.globalCompositeOperation = "source-over";
    surfCtx.clearRect(0,0,surfCanvas.width,surfCanvas.height);
    surfCtx.filter = "blur(" + FLUID_BLUR + "px) contrast(" + FLUID_CONTRAST + ")";
    surfCtx.drawImage(particleCanvas, 0, 0);
    surfCtx.filter = "none";

    coreCtx.setTransform(1,0,0,1,0,0);
    coreCtx.globalCompositeOperation = "source-over";
    coreCtx.clearRect(0,0,coreCanvas.width,coreCanvas.height);
    coreCtx.filter = "blur(" + FLUID_BLUR + "px) brightness(" + CORE_BRIGHTNESS + ") contrast(" + FLUID_CONTRAST + ")";
    coreCtx.drawImage(particleCanvas, 0, 0);
    coreCtx.filter = "none";

    // --- LAYER A: body. Deep, depth-graded blue fills the whole surface.
    ctx.drawImage(paintMask(surfCanvas, function(c){
        let g = c.createLinearGradient(0,0,0,canvas.height);
        g.addColorStop(0.0, "#2b8fd6");   // near the surface: brighter
        g.addColorStop(0.55,"#116bb0");
        g.addColorStop(1.0, "#063b66");   // deep: dark saturated blue
        return g;
    }), 0, 0);

    // --- LAYER B: thickness. Darken the interior so thick bodies of
    //     water read as deeper than thin films at the edges.
    ctx.save();
    ctx.globalAlpha = 0.55;
    ctx.drawImage(paintMask(coreCanvas, "#04284a"), 0, 0);
    ctx.restore();

    // --- LAYER C: refraction tint. A second, smaller-eroded core gives
    //     a teal inner glow like light passing through water.
    ctx.save();
