function renderWater(){
    // 1. soft white field from particle positions
    fieldCtx.clearRect(0,0,W,H);
    playground.drawFluid(fieldCtx);

    // 2. threshold into three nested crisp shells
    buildMask(bodyCtx, "goo-body");
    buildMask(coreCtx, "goo-core");
    buildMask(deepCtx, "goo-deep");

    // 3. refractive rim = body shell minus core (thin bright surface edge)
    rimCtx.setTransform(1,0,0,1,0,0);
    rimCtx.globalCompositeOperation = "source-over";
    rimCtx.clearRect(0,0,W,H);
    rimCtx.drawImage(bodyCanvas, 0, 0);
    rimCtx.globalCompositeOperation = "destination-out";
    rimCtx.drawImage(coreCanvas, 0, 0);
    rimCtx.globalCompositeOperation = "source-over";

    // LAYER A: body — depth-graded blue across the whole surface.
    paintMasked(bodyCanvas, function(c){
        let g = c.createLinearGradient(0,0,0,H);
        g.addColorStop(0.0, "#2e9fe6");
        g.addColorStop(0.6, "#1670b8");
        g.addColorStop(1.0, "#0a4a86");
        return g;
    });

    // LAYER B: thickness — darken interior so thick water reads deeper
    //          than thin films at the edges (the volume cue).
    paintMasked(coreCanvas, "#0c4680", 0.5);
    paintMasked(deepCanvas, "#05315c", 0.5);

    // LAYER C: refraction glow — faint teal light through the body.
    paintMasked(coreCanvas, "#27a6d8", 0.16, "lighter", 4);

    // LAYER D: refractive rim — bright glassy surface edge, top-lit.
    //          The single strongest "this is water" cue.
    paintMasked(rimCanvas, function(c){
        let g = c.createLinearGradient(0,0,0,H);
        g.addColorStop(0.0, "rgba(220,248,255,0.95)");
        g.addColorStop(1.0, "rgba(130,205,240,0.5)");
        return g;
    }, 1, "source-over", 0.6);

    // LAYER E: specular sheen — soft skylight on the upper surface.
    paintMasked(bodyCanvas, function(c){
        let g = c.createLinearGradient(0,0,0,H);
        g.addColorStop(0.0,  "rgba(255,255,255,0.35)");
        g.addColorStop(0.18, "rgba(255,255,255,0.04)");
        g.addColorStop(0.4,  "rgba(255,255,255,0.0)");
        return g;
    }, 1, "lighter");
}

let lastTime = performance.now();
let currentTime = 0;
let deltaTime = 0;

let playground = new Playground();

mainLoop();

function updatePlayground(dt){
    playground.update(dt);

    // background
    ctx.fillStyle = "#242321";
    ctx.fillRect(0,0, W, H);

    // water surface + shading
    renderWater();

    // obstacles & emitters crisply on top
    playground.draw();
}

function mainLoop(){
