const { chromium } = require('playwright');
(async () => {
  const url = 'file://' + require('path').resolve('12. Particle Collisions', 'Main.html');
  const browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 1320, height: 760 } });
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', e => errors.push(e.message));
  await page.goto(url);
  await page.waitForTimeout(parseInt(process.argv[3] || '16000', 10));
  await (await page.$('#canvas')).screenshot({ path: process.argv[2] || 'final.png' });
  await browser.close();
  if (errors.length) console.log('PAGE ERRORS:\n' + errors.join('\n'));
  console.log('saved');
})();

