// run the field through an SVG goo filter -> crisp white surface mask
function buildMask(tctx, filterId){
    tctx.setTransform(1,0,0,1,0,0);
    tctx.globalCompositeOperation = "source-over";
    tctx.clearRect(0,0,W,H);
    tctx.filter = "url(#" + filterId + ")";
    tctx.drawImage(fieldCanvas, 0, 0);
    tctx.filter = "none";
}

// paint `fill` clipped to a mask shape, composite onto main ctx.
// optional softBlur softens the mask edge first.
function paintMasked(maskCanvas, fill, alpha, op, softBlur){
    layerCtx.setTransform(1,0,0,1,0,0);
    layerCtx.globalCompositeOperation = "source-over";
    layerCtx.clearRect(0,0,W,H);
    layerCtx.filter = softBlur ? ("blur(" + softBlur + "px)") : "none";
    layerCtx.drawImage(maskCanvas, 0, 0);
    layerCtx.filter = "none";
    layerCtx.globalCompositeOperation = "source-in";
    layerCtx.fillStyle = (typeof fill === "function") ? fill(layerCtx) : fill;
    layerCtx.fillRect(0,0,W,H);
    layerCtx.globalCompositeOperation = "source-over";
    ctx.save();
    ctx.globalAlpha = (alpha === undefined ? 1 : alpha);
    ctx.globalCompositeOperation = op || "source-over";
    ctx.drawImage(layerCanvas, 0, 0);
    ctx.restore();
}

// edge crescent: the band of `src` left uncovered when `src` is
// shifted by (dx,dy). Shifting down (+dy) yields the TOP band, which
// is where a top-down light hits -> directional highlight/shadow.
// Result is left in bandCanvas (white on transparent).
function buildBand(src, dx, dy){
    bandCtx.setTransform(1,0,0,1,0,0);
    bandCtx.globalCompositeOperation = "source-over";
    bandCtx.clearRect(0,0,W,H);
    bandCtx.drawImage(src, 0, 0);
    bandCtx.globalCompositeOperation = "destination-out";
    bandCtx.drawImage(src, dx, dy);
    bandCtx.globalCompositeOperation = "source-over";
}

function renderWater(){
    // 1. soft white field from particle positions
    fieldCtx.clearRect(0,0,W,H);
    playground.drawFluid(fieldCtx);

    // 2. threshold into three nested crisp shells
    buildMask(bodyCtx, "goo-body");
    buildMask(coreCtx, "goo-core");
    buildMask(deepCtx, "goo-deep");

    // 3. refractive rim = body shell minus core (thin bright surface edge)
    rimCtx.setTransform(1,0,0,1,0,0);
    rimCtx.globalCompositeOperation = "source-over";
    rimCtx.clearRect(0,0,W,H);
    rimCtx.drawImage(bodyCanvas, 0, 0);
    rimCtx.globalCompositeOperation = "destination-out";
    rimCtx.drawImage(coreCanvas, 0, 0);
    rimCtx.globalCompositeOperation = "source-over";

    // LAYER A: body — depth-graded blue across the whole surface.
    paintMasked(bodyCanvas, function(c){
        let g = c.createLinearGradient(0,0,0,H);
        g.addColorStop(0.0, "#34a8ee");
        g.addColorStop(0.6, "#1670b8");
        g.addColorStop(1.0, "#093f74");
        return g;
    });

    // LAYER B: thickness — darken interior so thick water reads deeper
    //          than thin films at the edges (the volume cue).
    paintMasked(coreCanvas, "#0c4680", 0.45);
    paintMasked(deepCanvas, "#05315c", 0.5);

    // LAYER C: underside shadow — darken the BOTTOM edge of each body
    //          (light comes from above) to give rounded volume.
    buildBand(bodyCanvas, 0, -7);              // bottom band
    paintMasked(bandCanvas, "#04223f", 0.5, "source-over", 2);

    // LAYER D: directional highlight — bright crescent on the TOP-left
    //          of each body where the skylight hits. Reads as 3D water.
    buildBand(coreCanvas, 5, 9);               // top-left band
    paintMasked(bandCanvas, "#d8f5ff", 0.55, "lighter", 3);

    // LAYER E: refraction glow — faint teal light through the body.
    paintMasked(coreCanvas, "#27a6d8", 0.14, "lighter", 5);

