        <script>
            var canvas = document.getElementById("canvas");
            var ctx = canvas.getContext("2d");
            var W = canvas.width, H = canvas.height;

            function makeLayer(){ let c = document.createElement("canvas"); c.width = W; c.height = H; return c; }

            var fieldCanvas = makeLayer(), fieldCtx = fieldCanvas.getContext("2d");
            var bodyCanvas = makeLayer(), bodyCtx = bodyCanvas.getContext("2d");
            var coreCanvas = makeLayer(), coreCtx = coreCanvas.getContext("2d");
            var deepCanvas = makeLayer(), deepCtx = deepCanvas.getContext("2d");
            var rimCanvas  = makeLayer(), rimCtx  = rimCanvas.getContext("2d");
            var bandCanvas = makeLayer(), bandCtx = bandCanvas.getContext("2d");
            var layerCanvas= makeLayer(), layerCtx= layerCanvas.getContext("2d");

            var FLUID_RADIUS = 15, spriteSize = 64;
            var fluidSprite = document.createElement("canvas");
            fluidSprite.width = spriteSize; fluidSprite.height = spriteSize;
            (function(){
                let sctx = fluidSprite.getContext("2d");
                let g = sctx.createRadialGradient(spriteSize/2, spriteSize/2, 0, spriteSize/2, spriteSize/2, spriteSize/2);
                g.addColorStop(0.0, "rgba(255,255,255,1)");
                g.addColorStop(0.5, "rgba(255,255,255,1)");
                g.addColorStop(1.0, "rgba(255,255,255,0)");
                sctx.fillStyle = g; sctx.fillRect(0,0,spriteSize,spriteSize);
            })();
            window.fluidSprite = fluidSprite;
            window.FLUID_RADIUS = FLUID_RADIUS;

            function buildMask(tctx, filterId){
                tctx.setTransform(1,0,0,1,0,0);
                tctx.globalCompositeOperation = "source-over";
                tctx.clearRect(0,0,W,H);
                tctx.filter = "url(#" + filterId + ")";
                tctx.drawImage(fieldCanvas, 0, 0);
                tctx.filter = "none";
            }

            function paintMasked(maskCanvas, fill, alpha, op, softBlur){
                layerCtx.setTransform(1,0,0,1,0,0);
                layerCtx.globalCompositeOperation = "source-over";
                layerCtx.clearRect(0,0,W,H);
                layerCtx.filter = softBlur ? ("blur(" + softBlur + "px)") : "none";
                layerCtx.drawImage(maskCanvas, 0, 0);
                layerCtx.filter = "none";
                layerCtx.globalCompositeOperation = "source-in";
                layerCtx.fillStyle = (typeof fill === "function") ? fill(layerCtx) : fill;
                layerCtx.fillRect(0,0,W,H);
                layerCtx.globalCompositeOperation = "source-over";
                ctx.save();
                ctx.globalAlpha = (alpha === undefined ? 1 : alpha);
                ctx.globalCompositeOperation = op || "source-over";
                ctx.drawImage(layerCanvas, 0, 0);
                ctx.restore();
            }

            function buildBand(src, dx, dy){
                bandCtx.setTransform(1,0,0,1,0,0);
                bandCtx.globalCompositeOperation = "source-over";
                bandCtx.clearRect(0,0,W,H);
                bandCtx.drawImage(src, 0, 0);
                bandCtx.globalCompositeOperation = "destination-out";
                bandCtx.drawImage(src, dx, dy);
                bandCtx.globalCompositeOperation = "source-over";
            }

            function renderWater(){
                fieldCtx.clearRect(0,0,W,H);
                playground.drawFluid(fieldCtx);

                buildMask(bodyCtx, "goo-body");
                buildMask(coreCtx, "goo-core");
                buildMask(deepCtx, "goo-deep");

                rimCtx.setTransform(1,0,0,1,0,0);
                rimCtx.globalCompositeOperation = "source-over";
                rimCtx.clearRect(0,0,W,H);
                rimCtx.drawImage(bodyCanvas, 0, 0);
                rimCtx.globalCompositeOperation = "destination-out";
                rimCtx.drawImage(coreCanvas, 0, 0);
                rimCtx.globalCompositeOperation = "source-over";

                paintMasked(bodyCanvas, "#0a3a66", 0.35, "source-over", 6);

                paintMasked(bodyCanvas, function(c){
                    let g = c.createLinearGradient(0,0,0,H);
                    g.addColorStop(0.0, "#73cdf4");
                    g.addColorStop(0.5, "#1c82c8");
                    g.addColorStop(1.0, "#093e72");
                    return g;
                });

                paintMasked(coreCanvas, "#0d5091", 0.5);
                paintMasked(deepCanvas, "#062f57", 0.6);

                buildBand(bodyCanvas, 0, -7);
                paintMasked(bandCanvas, "#04203c", 0.5, "source-over", 2);

                buildBand(coreCanvas, 5, 9);
                paintMasked(bandCanvas, "#dff6ff", 0.5, "lighter", 3);

                paintMasked(deepCanvas, "#2bb0e0", 0.12, "lighter", 5);

                paintMasked(rimCanvas, "rgba(236,250,255,0.55)", 1, "source-over", 1.5);

                paintMasked(rimCanvas, function(c){
                    let g = c.createLinearGradient(0,0,0,H);
                    g.addColorStop(0.0, "rgba(255,255,255,0.85)");
                    g.addColorStop(0.5, "rgba(170,222,248,0.18)");
                    g.addColorStop(1.0, "rgba(120,195,235,0.0)");
                    return g;
                }, 1, "lighter", 0.5);

                paintMasked(coreCanvas, function(c){
                    let g = c.createLinearGradient(0,0,0,H);
                    g.addColorStop(0.0,  "rgba(255,255,255,0.4)");
                    g.addColorStop(0.16, "rgba(255,255,255,0.05)");
                    g.addColorStop(0.4,  "rgba(255,255,255,0.0)");
                    return g;
                }, 1, "lighter", 2);
            }

            let lastTime = performance.now();
            let deltaTime = 0;
            let playground = new Playground();
            mainLoop();

            function updatePlayground(dt){
                playground.update(dt);
                ctx.fillStyle = "#242321";
                ctx.fillRect(0,0, W, H);
                renderWater();
                playground.draw();
            }

            function mainLoop(){
                window.requestAnimationFrame(mainLoop);
                let currentTime = performance.now();
                deltaTime = (currentTime - lastTime) / 1000;
                updatePlayground(deltaTime);
                lastTime = currentTime;
            }

            function getMousePos(canvas, evt){
                var rect = canvas.getBoundingClientRect();
                return { x: evt.clientX - rect.left, y: evt.clientY - rect.top };
            }
            canvas.addEventListener('mousemove', function(evt){
                let mouse = getMousePos(canvas,evt);
                playground.onMouseMove(new Vector2(mouse.x,mouse.y));
            }, false)
            canvas.addEventListener('mousedown', function(evt){ playground.onMouseDown(evt.button); }, false)
            canvas.addEventListener('mouseup', function(evt){ playground.onMouseUp(evt.button); }, false)
        </script>
    </body>
</html>
