            var deepCanvas = makeLayer(), deepCtx = deepCanvas.getContext("2d");
            var rimCanvas  = makeLayer(), rimCtx  = rimCanvas.getContext("2d");
            var bandCanvas = makeLayer(), bandCtx = bandCanvas.getContext("2d");
            var layerCanvas= makeLayer(), layerCtx= layerCanvas.getContext("2d");

