            var ctx = canvas.getContext("2d");
            var W = canvas.width, H = canvas.height;

            function makeLayer(){ let c = document.createElement("canvas"); c.width = W; c.height = H; return c; }

            var fieldCanvas = makeLayer(), fieldCtx = fieldCanvas.getContext("2d");
            var foamCanvas  = makeLayer(), foamCtx  = foamCanvas.getContext("2d");
            var bodyCanvas = makeLayer(), bodyCtx = bodyCanvas.getContext("2d");
            var coreCanvas = makeLayer(), coreCtx = coreCanvas.getContext("2d");
            var deepCanvas = makeLayer(), deepCtx = deepCanvas.getContext("2d");
            var rimCanvas  = makeLayer(), rimCtx  = rimCanvas.getContext("2d");
            var bandCanvas = makeLayer(), bandCtx = bandCanvas.getContext("2d");
            var causCanvas = makeLayer(), causCtx = causCanvas.getContext("2d");
            var layerCanvas= makeLayer(), layerCtx= layerCanvas.getContext("2d");

            var FLUID_RADIUS = 15, spriteSize = 64;
            function softSprite(stops){
                let s = document.createElement("canvas"); s.width = spriteSize; s.height = spriteSize;
                let c = s.getContext("2d");
                let g = c.createRadialGradient(spriteSize/2,spriteSize/2,0,spriteSize/2,spriteSize/2,spriteSize/2);
                stops.forEach(function(st){ g.addColorStop(st[0], st[1]); });
                c.fillStyle = g; c.fillRect(0,0,spriteSize,spriteSize); return s;
            }
            var fluidSprite = softSprite([[0,"rgba(255,255,255,1)"],[0.5,"rgba(255,255,255,1)"],[1,"rgba(255,255,255,0)"]]);
            var foamSprite  = softSprite([[0,"rgba(255,255,255,0.9)"],[0.35,"rgba(255,255,255,0.5)"],[1,"rgba(255,255,255,0)"]]);
            window.fluidSprite = fluidSprite;
            window.FLUID_RADIUS = FLUID_RADIUS;

            // caustics tile: soft bright dapples, scrolled at runtime
            var causTile = document.createElement("canvas"), causTileSize = 256;
            causTile.width = causTileSize; causTile.height = causTileSize;
            (function(){
                let c = causTile.getContext("2d"); let seed = 1234567;
                function rnd(){ seed = (seed*1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; }
                for (let i=0;i<26;i++){
                    let x=rnd()*causTileSize, y=rnd()*causTileSize, r=18+rnd()*40;
                    let g=c.createRadialGradient(x,y,0,x,y,r);
                    g.addColorStop(0,"rgba(255,255,255,0.9)"); g.addColorStop(1,"rgba(255,255,255,0)");
                    c.fillStyle=g; c.beginPath(); c.arc(x,y,r,0,Math.PI*2); c.fill();
                }
            })();

            function buildMask(tctx, filterId){
                tctx.setTransform(1,0,0,1,0,0); tctx.globalCompositeOperation="source-over";
                tctx.clearRect(0,0,W,H); tctx.filter="url(#"+filterId+")";
                tctx.drawImage(fieldCanvas,0,0); tctx.filter="none";
            }
            function paintMasked(maskCanvas, fill, alpha, op, softBlur){
                layerCtx.setTransform(1,0,0,1,0,0); layerCtx.globalCompositeOperation="source-over";
                layerCtx.clearRect(0,0,W,H);
                layerCtx.filter = softBlur ? ("blur("+softBlur+"px)") : "none";
                layerCtx.drawImage(maskCanvas,0,0); layerCtx.filter="none";
                layerCtx.globalCompositeOperation="source-in";
                layerCtx.fillStyle=(typeof fill==="function")?fill(layerCtx):fill;
                layerCtx.fillRect(0,0,W,H); layerCtx.globalCompositeOperation="source-over";
                ctx.save();
                ctx.globalAlpha=(alpha===undefined?1:alpha);
                ctx.globalCompositeOperation=op||"source-over";
                ctx.drawImage(layerCanvas,0,0); ctx.restore();
            }
            function buildBand(src, dx, dy){
                bandCtx.setTransform(1,0,0,1,0,0); bandCtx.globalCompositeOperation="source-over";
                bandCtx.clearRect(0,0,W,H); bandCtx.drawImage(src,0,0);
                bandCtx.globalCompositeOperation="destination-out"; bandCtx.drawImage(src,dx,dy);
                bandCtx.globalCompositeOperation="source-over";
            }
            function tileCaustics(tctx, offx, offy){
                tctx.setTransform(1,0,0,1,0,0); tctx.globalCompositeOperation="source-over";
                tctx.clearRect(0,0,W,H);
                let ox=((offx%causTileSize)+causTileSize)%causTileSize;
                let oy=((offy%causTileSize)+causTileSize)%causTileSize;
                for(let x=-causTileSize+ox;x<W;x+=causTileSize)
                    for(let y=-causTileSize+oy;y<H;y+=causTileSize)
                        tctx.drawImage(causTile,x,y);
            }

            // whitewater: render fast-moving particles into a foam field. Turbulent
            // / splashing water aerates -> bright foam. (the strongest water cue)
            function buildFoamField(){
                foamCtx.setTransform(1,0,0,1,0,0); foamCtx.globalCompositeOperation="source-over";
                foamCtx.clearRect(0,0,W,H);
                let ps = playground.simulation.particles;
                let r = 11, d = r*2;
                for (let i=0;i<ps.length;i++){
                    let v = ps[i].velocity;
                    let speed = Math.sqrt(v.x*v.x + v.y*v.y);
                    let a = (speed - 7) / 16;            // ramp foam in with speed
                    if (a <= 0) continue;
                    foamCtx.globalAlpha = a > 1 ? 1 : a;
                    let p = ps[i].position;
                    foamCtx.drawImage(foamSprite, p.x-r, p.y-r, d, d);
                }
                foamCtx.globalAlpha = 1;
            }

            function renderWater(time){
                fieldCtx.clearRect(0,0,W,H);
                playground.drawFluid(fieldCtx);

                buildMask(bodyCtx, "goo-body");
                buildMask(coreCtx, "goo-core");
                buildMask(deepCtx, "goo-deep");

                rimCtx.setTransform(1,0,0,1,0,0); rimCtx.globalCompositeOperation="source-over";
                rimCtx.clearRect(0,0,W,H); rimCtx.drawImage(bodyCanvas,0,0);
                rimCtx.globalCompositeOperation="destination-out"; rimCtx.drawImage(coreCanvas,0,0);
                rimCtx.globalCompositeOperation="source-over";

                // A: glassy translucent body, sky-lit cyan top -> deep navy
                paintMasked(bodyCanvas, function(c){
                    let g=c.createLinearGradient(0,0,0,H);
                    g.addColorStop(0.0,"rgba(122,205,244,0.92)");
                    g.addColorStop(0.5,"rgba(28,128,196,0.95)");
                    g.addColorStop(1.0,"rgba(9,58,108,0.98)");
                    return g;
                });

                // B: depth/volume
                paintMasked(coreCanvas, "#0d5091", 0.45);
                paintMasked(deepCanvas, "#062f57", 0.55);

                // C: caustics -- scrolling dappled light inside the body
                causCtx.setTransform(1,0,0,1,0,0); causCtx.globalCompositeOperation="source-over";
                causCtx.clearRect(0,0,W,H);
                tileCaustics(bandCtx, time*14, time*6);
                causCtx.globalAlpha=0.5; causCtx.drawImage(bandCanvas,0,0);
                tileCaustics(bandCtx, -time*9+80, time*11+40);
                causCtx.globalAlpha=0.5; causCtx.drawImage(bandCanvas,0,0);
                causCtx.globalAlpha=1; causCtx.globalCompositeOperation="destination-in";
                causCtx.drawImage(coreCanvas,0,0);
                ctx.save();
                ctx.globalCompositeOperation="soft-light"; ctx.globalAlpha=0.5; ctx.drawImage(causCanvas,0,0);
                ctx.globalCompositeOperation="lighter"; ctx.globalAlpha=0.16; ctx.drawImage(causCanvas,0,0);
                ctx.restore();

                // D: underside shadow
                buildBand(bodyCanvas, 0, -6);
                paintMasked(bandCanvas, "#04203c", 0.45, "source-over", 2);

                // E: directional highlight on top-left edge
                buildBand(coreCanvas, 6, 10);
                paintMasked(bandCanvas, "#eafaff", 0.55, "lighter", 3);

                // F: whitewater foam from fast particles, clipped to the surface
                buildFoamField();
                foamCtx.globalCompositeOperation="destination-in";
                foamCtx.drawImage(bodyCanvas,0,0);
                foamCtx.globalCompositeOperation="source-over";
                ctx.save();
                ctx.globalCompositeOperation="lighter"; ctx.globalAlpha=0.85; ctx.drawImage(foamCanvas,0,0);
                ctx.restore();

                // G: thin glassy glint, additive & top-biased
                paintMasked(rimCanvas, function(c){
                    let g=c.createLinearGradient(0,0,0,H);
                    g.addColorStop(0.0,"rgba(255,255,255,0.7)");
                    g.addColorStop(0.45,"rgba(165,220,248,0.1)");
                    g.addColorStop(1.0,"rgba(120,195,235,0.0)");
                    return g;
                }, 1, "lighter", 0.4);

                // H: specular sheen
                paintMasked(coreCanvas, function(c){
                    let g=c.createLinearGradient(0,0,0,H);
                    g.addColorStop(0.0,"rgba(255,255,255,0.4)");
                    g.addColorStop(0.14,"rgba(255,255,255,0.05)");
                    g.addColorStop(0.36,"rgba(255,255,255,0.0)");
                    return g;
                }, 1, "lighter", 2);
            }

            let lastTime = performance.now();
            let deltaTime = 0;
            let playground = new Playground();
            mainLoop();

            function updatePlayground(dt){
                playground.update(dt);
                ctx.fillStyle="#242321"; ctx.fillRect(0,0,W,H);
                renderWater(performance.now()/1000);
                playground.draw();
            }
            function mainLoop(){
                window.requestAnimationFrame(mainLoop);
                let currentTime=performance.now();
                deltaTime=(currentTime-lastTime)/1000;
                updatePlayground(deltaTime);
                lastTime=currentTime;
            }
            function getMousePos(canvas, evt){
                var rect=canvas.getBoundingClientRect();
                return { x: evt.clientX-rect.left, y: evt.clientY-rect.top };
            }
            canvas.addEventListener('mousemove', function(evt){
                let mouse=getMousePos(canvas,evt);
                playground.onMouseMove(new Vector2(mouse.x,mouse.y));
            }, false)
            canvas.addEventListener('mousedown', function(evt){ playground.onMouseDown(evt.button); }, false)
            canvas.addEventListener('mouseup', function(evt){ playground.onMouseUp(evt.button); }, false)
        </script>
    </body>
</html>
