const { chromium } = require('playwright');
(async () => {
  const url = 'file://' + require('path').resolve('12. Particle Collisions', 'Main.html');
  const b = await chromium.launch();
  const p = await b.newPage({ viewport: { width: 1320, height: 760 } });
  const errs = [];
  p.on('console', m => { if (m.type()==='error') errs.push(m.text()); });
  p.on('pageerror', e => errs.push(e.message));
  await p.goto(url);
  await p.waitForTimeout(parseInt(process.argv[3]||'16000',10));
  await (await p.$('#canvas')).screenshot({ path: process.argv[2]||'out.png' });
  await b.close();
  console.log(errs.length ? ('PAGE ERRORS:\n'+errs.join('\n')) : 'no page errors');
})();
